# Edge reverse proxy for the JSON API.
#
# The container runs unprivileged (uid 101) and listens on 8080; compose maps
# the host port. TLS is expected to be terminated upstream (load balancer or a
# separate terminator) -- if nginx terminates TLS, add the server block and
# HSTS here, and forward X-Forwarded-Proto accordingly.

worker_processes auto;
worker_rlimit_nofile 8192;
pid /var/run/nginx.pid;

error_log /dev/stderr warn;

events {
    worker_connections 1024;
    multi_accept on;
    use epoll;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;

    # Do not advertise the nginx version.
    server_tokens off;

    log_format main '$remote_addr - $request_id [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" rt=$request_time ut=$upstream_response_time';

    # Symlinked to the container's stdout/stderr by the image.
    access_log /dev/stdout main;

    sendfile           on;
    tcp_nopush         on;
    tcp_nodelay        on;
    keepalive_timeout  65s;
    types_hash_max_size 2048;

    # Slow-client protection. Uploads are JSON, so 2 MB is generous.
    client_max_body_size    2m;
    client_body_timeout     15s;
    client_header_timeout   15s;
    send_timeout            30s;
    reset_timedout_connection on;

    # Drain request bodies even for handlers that do not read them, so the
    # client sees the response instead of a connection reset.
    client_body_buffer_size 128k;

    # gzip JSON only for reasonably large payloads.
    gzip              on;
    gzip_vary         on;
    gzip_min_length   1024;
    gzip_proxied      any;
    gzip_types        application/json application/problem+json text/plain;

    upstream api {
        server api:8000;
        # Keep-alive pool to gunicorn (proxy_http_version 1.1 + Connection ""
        # below are required for this to be used).
        keepalive 32;
        keepalive_timeout 60s;
    }

    server {
        listen      8080 default_server;
        server_name _;

        # Security headers. `always` makes them apply to error responses too.
        add_header X-Content-Type-Options nosniff always;
        add_header X-Frame-Options DENY always;
        add_header Referrer-Policy no-referrer always;

        # Never serve dotfiles (.env, .git, ...) if a path escapes the proxy.
        location ~ /\. {
            deny all;
        }

        # Liveness/readiness passthrough used by the compose healthcheck.
        location = /healthz {
            access_log off;
            proxy_pass http://api;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host $host;
            proxy_connect_timeout 2s;
            proxy_read_timeout 3s;
            proxy_send_timeout 3s;
        }

        location / {
            proxy_pass http://api;

            proxy_http_version 1.1;
            proxy_set_header Connection "";

            # This proxy is the trust boundary: overwrite (do not append to)
            # client-supplied forwarding headers so the API cannot be lied to.
            proxy_set_header Host              $host;
            proxy_set_header X-Real-IP         $remote_addr;
            proxy_set_header X-Forwarded-For   $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Forwarded-Host  $host;
            proxy_set_header X-Forwarded-Port  $server_port;
            proxy_set_header X-Request-ID      $request_id;

            # JSON APIs answer quickly; a hung upstream should not hold a
            # client connection for the nginx default of 60s.
            proxy_connect_timeout 5s;
            proxy_send_timeout    30s;
            proxy_read_timeout    30s;

            # Buffer small JSON responses; the API is not a streaming service.
            proxy_buffering       on;
            proxy_buffer_size     16k;
            proxy_buffers         8 16k;
            proxy_busy_buffers_size 32k;

            proxy_hide_header X-Powered-By;

            # Do not silently retry non-idempotent requests: only the default
            # connect/send errors are retried, and there is one upstream.
            proxy_next_upstream error timeout;

            # JSON-shaped error instead of nginx's HTML error page.
            error_page 502 503 504 = @upstream_unavailable;
        }

        location @upstream_unavailable {
            default_type application/json;
            add_header Retry-After 5 always;
            add_header X-Content-Type-Options nosniff always;
            return 503 '{"error":"service_unavailable"}';
        }
    }
}

